job_description:
At Alamar, we are passionate about enabling our customers to make scientific discoveries that translate into clinical outcomes and benefit patients. Our team is growing quickly as we develop innovative approaches to measure critical protein biomarkers from liquid samples that can enable the earliest possible detection of disease. We believe the next frontier in biology is enabled by measuring proteins at higher sensitivity in highly multiplexed assays at the push of a button, which is something only Alamar can do. As we build our team, we seek collaborative, driven, intellectually curious people committed to solving complex challenges. Our culture rewards accountability and cross functional teamwork because we believe this enables the kind of breakthrough thinking that will accelerate our mission.
We are searching for a Technical Support Scientist – EMEA with a strong background in biological sciences and an eagerness to work with customers to ensure their success with Alamar products.  This role will join a dynamic team of professionals as our first Technical Support Scientist in Europe.  This role will leverage your expertise to provide scientific and technical support to Alamar’s automated instrument system for high-precision proteomic analysis. Reporting to the Supervisor, Technical Support you will collaborate closely with the sales, marketing and research and development teams to continue to enhance our products and grow our business.  The Technical Support Scientist will be the front-line support path for our customers and will take ownership of the resolution of all inquiries and complaints.  This is a hands-on role that offers the opportunity to make a significant impact on life science research and early disease diagnosis within a rapidly expanding company. &nbsp;
Responsibilities: &nbsp;
• Serve as a primary point of contact for customers for technical and scientific support, working collaboratively with other Technical and Application Support team members to coordinate responses, share context, and ensure consistent, high-quality support. &nbsp;
• Logging cases and associated communications and resolutions in the CRM&nbsp;
• Informing requirements for scaling support process and infrastructure  &nbsp;
• Tracking support metrics &nbsp;
• Perform platform demonstrations as needed to support sales &nbsp;
• As a foundational member of the team, contribute to the building of the technical knowledgebase and processes to facilitate scaling of support as the user base expands &nbsp;
• Collaborate with internal R&amp;D teams during the product development cycle, providing critical insights via Voice of Customer&nbsp;
• Contribute to the creation of customer training materials and documentation, working closely with internal resources&nbsp;
• Assist in the scaling of our CRM toolset, ensuring effective integration with ERP and marketing automation&nbsp;
Qualifications: &nbsp;
• BS, MS or PhD in the biological sciences &nbsp;
• At least two years in a scientific customer support role&nbsp;
• Demonstrated experience in the generation of technical documentation &nbsp;
• Pragmatic thinker with a clear and effective approach to problem-solving&nbsp;
• Strong orientation towards process improvement and unwavering commitment to quality&nbsp;
• In-depth understanding of preparing materials to enhance customer support &nbsp;
• Excellent relationship-building skills, with the ability to engage effectively with diverse personalities both inside and outside the company&nbsp;
• Outstanding written, verbal, and presentation skills, capable of conveying complex information with clarity&nbsp;
• If you are a dedicated individual with a passion for advancing disease detection, we invite you to join our innovative team at Alamar Biosciences. You will have the opportunity to shape the future of proteomics and make a meaningful impact on the world of scientific research and healthcare&nbsp;
Alamar offers a competitive compensation package appropriate to the position and local market. Compensation may include salary, bonus, equity, and benefits, as applicable, and is determined based on factors such as work location, relevant experience, skills, qualifications, and education. Additional details regarding compensation and benefits will be discussed during the recruitment process.
Please Note - We participate in E-Verify to confirm authorization to work in the United States.

const FEED_URL = "https://barbour.current-vacancies.com/RSSFeeds/Vacancies/JBARBOURAN?feedID=1F08B4E31D4F4ACF9C892BFF32551FD3";
document.addEventListener("DOMContentLoaded", async () => {
const container = document.getElementById("job-detail");
if (!container) {
console.error("Missing #job-detail container in HTML.");
return;
}
// Get VacancyID from URL query string: /vacancies/apply/?v=VacancyID
const urlParams = new URLSearchParams(window.location.search);
const vacancyId = urlParams.get('v');
if (!vacancyId) {
container.innerHTML = "Invalid job reference. Please go back to the vacancies page.
";
return;
}
try {
container.classList.add('loading');
const response = await fetch(FEED_URL);
if (!response.ok) throw new Error(`HTTP ${response.status}`);
const xmlText = await response.text();
const parser = new DOMParser();
const xml = parser.parseFromString(xmlText, "application/xml");
if (xml.querySelector("parsererror")) throw new Error("Invalid XML structure");
const vacancies = xml.querySelectorAll("item");
let matchedVacancy = null;
// Find the matching vacancy by VacancyID
for (const vac of vacancies) {
const id = vac.querySelector("VacancyID")?.textContent?.trim();
if (id === vacancyId) {
matchedVacancy = vac;
break;
}
}
if (!matchedVacancy) {
container.innerHTML = 'Vacancy not found. See All Vacancies
'
container.classList.remove('loading');
return;
}
// Extract details
const jobDetails = {
link: matchedVacancy.querySelector("link")?.textContent?.trim() || "#",
id: matchedVacancy.querySelector("VacancyID")?.textContent?.trim() || "",
title: matchedVacancy.querySelector("VacancyTitle")?.textContent?.trim() || "Untitled",
location: matchedVacancy.querySelector("Location")?.textContent?.trim() || "Unknown",
contractType: matchedVacancy.querySelector("ContractType")?.textContent?.trim() || "",
workplace: matchedVacancy.querySelector("Workplace")?.textContent?.trim() || "",
jobType: matchedVacancy.querySelector("JobType")?.textContent?.trim() || "",
advertHTML: matchedVacancy.querySelector("Advert")?.textContent || "",
expiry: matchedVacancy.querySelector("ExpiryDate")?.textContent || ""
};
// Inject into page
container.innerHTML = `
${jobDetails.title}
Apply Now
${jobDetails.location}
ID: ${jobDetails.id}
${jobDetails.advertHTML}
Applications close: ${jobDetails.expiry}
Apply Now
`;
} catch (err) {
console.error("Error fetching RSS feed:", err); container.innerHTML = "Unable to load job details. Please try again later.
";
}
container.classList.remove('loading');
// 🔹 Refresh fade-in observer for dynamically added elements
if (window.FxFadeInInstance) {
window.FxFadeInInstance.update(container);
} else if (typeof FxFadeIn === "function") {
window.FxFadeInInstance = new FxFadeIn();
window.FxFadeInInstance.update(container);
} });
(function ($) {
$(document).ready(function () {
$.support.cors = true;
$.addTemplateFormatter({
vacancyLink: function (value) {
return "vacancy-details/" + value;
},
gbdate: function (value) {
return new Date(value).toLocaleDateString('en-GB');
},
documentLink: function (value) {
return "https://octoapi.blueoctopus.co.uk/api/" + value;
},
});
function RunSearch() {
const params = new URLSearchParams(window.location.search);
const vid = params.get('v'); // Gets the number after ?v=
if (!vid) {
// console.error('Vacancy ID not found in URL.');
return;
}
const container = $('#vacancy');
// console.log('Vacancy ID:', vid);
// Show loading state
const loading = $('
').text('Loading...').attr('id', 'loading-state');
container.append(loading);
$.ajax({
url: 'https://octoapi.blueoctopus.co.uk/api/GetVacancyByCompany?vacancyid=' + vid + '&companyId=1661&blueoctopuscouk=false',
success: function (response) {
$('#loading-state').remove();
// console.log(response);
container.empty(); // Clear previous content
const header = $('').appendTo(container);
$('
').text(response.VacancyTitle).appendTo(header);
$('')
.attr('href', response.ApplicationUrl)
.text('Apply Now')
.attr('target', '_blank')
.addClass('btn')
.appendTo(header);
// Create job-meta container for salary, location, expiry
const jobMeta = $('
').appendTo(container);
$('
')
.html('' + response.AdvertisedLocation)
.appendTo(jobMeta);
$('
')
.html('' + response.AdvertisedSalary)
.appendTo(jobMeta);
// Add advertisement text
$('
').html(response.AdvertisementText).appendTo(container);
$('
')
.html('Expiry Date: ' + new Date(response.ExpiryDate).toLocaleDateString('en-GB'))
.appendTo(container);
$('')
.attr('href', response.ApplicationUrl)
.text('Apply Now')
.attr('target', '_blank')
.addClass('btn mt-3 mt-sm-4')
.appendTo(container);
// if (response.Documents.length > 0) {
// const docSection = $('
').attr('id', 'documents');
// $('
').text('Documents').appendTo(docSection);
// response.Documents.forEach(doc => {
// $('')
// .attr('href', 'https://octoapi.blueoctopus.co.uk/api/' + doc)
// .text(doc)
// .attr('target', '_blank')
// .css('display', 'block')
// .appendTo(docSection);
// });
// container.append(docSection);
// }
},
error: function (xhr, ajaxOptions, thrownError) {
$('#loading-state').remove();
container.append($('
').text('Failed to load vacancy details. Please try again.'));
// console.error('Error fetching vacancy:', xhr.status, thrownError);
}
});
}
// Call the function so it runs on page load
RunSearch();
});
})(jQuery);

