async function getData(url = '') {
const config = {
method: 'GET',
mode: 'cors',
cache: 'no-cache',
credentials: 'same-origin',
headers: { "Content-Type": "application/json; charset=utf-8" },
redirect: 'follow',
referrerPolicy: 'no-referrer'
};
const response = await fetch(url, config);
return response.json();
}
function populateJobDetails() {
let details = document.getElementById('job-details');
details.innerHTML = window.job.content;
try {
let h1 = document.querySelector('.hisc-subpage-hero h1');
h1.innerHTML = decodeEntities(window.job.title);
let heroBody = document.querySelector('.score-hero-body');
heroBody.innerHTML = window.job.summary;
let location = document.querySelector('.score-call-to-action .location');
location.innerHTML = `${window.job.locationName ?? ''}`;
} catch (error) { console.log("Sub-page Hero not found on page.") }
// let liscript = document.getElementById('linked-in-script');
// liscript.dataset.companyJobCode = window.job.id;
let structured = document.getElementById('structured-data');
structured.innerHTML = window.job.structuredData;
}
function populateJobQuestions() {
let form = document.getElementById('dynamic-fields');
let optionalHtml = `
Optional
`;
let requiredHtml = `
This field is required.
`;
let validHtml = `
Looks good!
`;
let hasEEOCLeadInRendered = false;
window.job.questions.forEach((question) => {
if (question.fields[0].name == "veteran_status")
return;
let eeoc = '';
let qHtml = ``;
if (question.fields[0].type == "input_text") {
if (question.fields[0].name == "phone") {
qHtml += `
${question.label}
Invalid phone number format. Use xxx-xxx-xxxx
${validHtml}`;
} else if (question.fields[0].name == "email") {
qHtml += `
${question.label}
Please enter a valid email address.
${validHtml}`;
} else {
qHtml += `
${question.label}
${question.required ? requiredHtml : optionalHtml}
${validHtml}`;
}
} else if (question.fields[0].type == "input_file") {
qHtml += `
${question.label}
${question.required ? requiredHtml : optionalHtml}
${validHtml}
