// Check file size for uploads
function addFileSizeListeners() {
let fileinputs = document.querySelectorAll('input[type=file]');
let maxSizeMB = 5;
Array.prototype.slice.call(fileinputs)
.forEach(async function (input) {
input.addEventListener('change', async (event) => {
let isValid = input.checkValidity();
let file = event.currentTarget.files[0];
let filesize = (file.size / 1024 / 1024).toFixed(4); // Convert to MB
let isRightSized = filesize new Promise((resolve, reject) => {
const reader = new FileReader();
reader.readAsDataURL(file);
reader.onload = () => resolve(reader.result.split("base64,")[1].trim());
reader.onerror = error => reject(error);
});
function delay(t, v) {
return new Promise(function (resolve) {
setTimeout(resolve.bind(null, v), t)
});
}
Promise.prototype.delay = function (t) {
return this.then(function (v) {
return delay(t, v);
});
}
function getUrlParameter(location, name) {
name = name.replace(/[\[]/, '\\[').replace(/[\]]/, '\\]');
let regex = new RegExp('[\\?&]' + name + '=([^&#]*)');
let results = regex.exec(location);
return results === null ? null : decodeURIComponent(results[1].replace(/\+/g, ' '));
}
function isNullOrWhitespace(input) {
return !input || !input.trim();
}
function addSubmitListeners() {
// Fetch all the forms we want to apply custom Bootstrap validation styles to
var forms = document.querySelectorAll('.needs-validation')
window.CanSubmit = true;
// Loop over them and prevent submission
Array.prototype.slice.call(forms)
.forEach( (form) => {
form.addEventListener('submit', async (event) => {
let isValid = form.checkValidity();
form.classList.add('was-validated')
event.preventDefault()
event.stopPropagation()
if (!isValid) {
document.querySelector('#app').scrollIntoView();
return;
}
let sending = document.getElementById('sending');
sending.classList.toggle('d-none');
let spinner = document.getElementById('loading-spinner');
spinner.classList.toggle('d-none');
let btn = document.getElementById('jump-to-app-btn');
btn.classList.toggle('d-none');
let application = document.getElementById('application');
application.classList.toggle('d-none');
delay(5)
.then(() => {
let dlData = {
'event': 'honor-app-form-submit',
'job_id': window.job.id || null,
'form_id': 'honor-app-form-submit',
'eventCallback': () => {
delay(1500)
.then(async () => {
if (window.CanSubmit) {
window.CanSubmit = false;
await SubmitToAPI(form);
}
});
}
};
window.dataLayer = window.dataLayer || [];
window.dataLayer.push(dlData);
});
}, false)
});
}
async function SubmitToAPI(form) {
let subAPI = "https://webmarketingapi-careers.azurewebsites.net/api/v1/honor-careers/career/submit";
let formData = new FormData(form);
