if (isNullOrWhitespace(window.jobCode)) {
window.location = '/honor-careers/';
}
getData("https://webmarketingapi-careers.azurewebsites.net/api/v1/honor-careers/career" + "?jobID=" + window.jobCode)
.then((response) => {
